return $input.all().map(item => {
  const t = item.json;
  const s = t.documento || {};

  let cola;
  let razon;
  let alerta = "";

  if (s.es_documento_compras === undefined) {
    cola = "revision_humana";
    razon = "No se pudo extraer el documento";
  } else if (s.es_documento_compras === false) {
    cola = "fuera_de_alcance";
    razon = "El documento no pertenece al proceso de compras";
  } else if (t.campos_faltantes.length > 0) {
    cola = "revision_humana";
    razon = `Faltan campos obligatorios: ${t.campos_faltantes.join(", ")}`;
  } else if (!t.oc_valida) {
    cola = "revision_humana";
    razon = "La orden de compra no existe";
  } else if (!t.recepcion_confirmada) {
    cola = "revision_humana";
    razon = "La recepción de mercancía no está confirmada";
  } else if (!t.proveedor_coincide) {
    cola = "revision_humana";
    razon = "El proveedor no coincide con la orden de compra";
  } else if (!t.total_coincide || !t.moneda_coincide) {
    cola = "revision_humana";
    razon = "El importe o la moneda no coinciden con la orden de compra";
  } else {
    cola = "confirmacion_humana";
    razon = "Documento completo y consistente con la orden de compra";
  }

  return {
    json: {
      ...t,
      cola,
      razon,
      alerta
    }
  };
});

const verificar = {
  B1: (r) =>
    r.oc_valida === true &&
    r.proveedor_coincide === true &&
    r.total_coincide === true &&
    r.campos_faltantes.length === 0 &&
    r.cola === "confirmacion_humana",

  B2: (r) =>
    r.numero_oc === null &&
    r.cola === "revision_humana",

  B3: (r) =>
    r.documento?.es_documento_compras === false &&
    r.cola === "fuera_de_alcance"
};

return $input.all().map(item => {
  const r = item.json;

  let paso = false;
  let error = r.error ? String(r.error) : "";

  try {
    paso = !error && Boolean(verificar[r.id](r));
  } catch (e) {
    error = error || `Error al verificar: ${e.message}`;
  }

  return {
    json: {
      template: "N8-B",
      id: r.id,
      tipo: r.tipo,
      entrada: r.entrada,
      esperado: r.esperado,
      criterio: r.criterio,
      observado: JSON.stringify({
        tipo_documento: r.documento?.tipo_documento,
        proveedor_rfc: r.documento?.proveedor_rfc,
        numero_factura: r.documento?.numero_factura,
        numero_oc: r.numero_oc,
        total: r.documento?.total,
        oc_valida: r.oc_valida,
        campos_faltantes: r.campos_faltantes,
        cola: r.cola,
        razon: r.razon
      }),
      veredicto_auto: paso ? "PASS" : "FAIL",
      veredicto_final: "",
      error
    }
  };
});

const ORDENES = [
  {
    numero_oc: "OC-4587",
    proveedor_rfc: "ANO230101XX1",
    proveedor_nombre: "Alimentos del Norte S.A. de C.V.",
    total_esperado: 14500,
    moneda: "MXN",
    recepcion_confirmada: true
  },
  {
    numero_oc: "OC-4612",
    proveedor_rfc: "ERE240101AA1",
    proveedor_nombre: "Envases Regios S.A. de C.V.",
    total_esperado: 8350,
    moneda: "MXN",
    recepcion_confirmada: true
  }
];

const casos = $("Casos de prueba").all().map(i => i.json);

return $input.all().map((item, i) => {
  const s = item.json.output ?? {};

  const oc = ORDENES.find(o => o.numero_oc === s.numero_oc);

  const obligatorios = [
    "proveedor_nombre",
    "proveedor_rfc",
    "numero_factura",
    "fecha_emision",
    "numero_oc",
    "total",
    "moneda"
  ];

  const campos_faltantes = obligatorios.filter(
    campo => s[campo] === null || s[campo] === undefined || s[campo] === ""
  );

  const proveedor_coincide = oc
    ? String(s.proveedor_rfc || "").toUpperCase() === oc.proveedor_rfc
    : false;

  const total_coincide = oc
    ? Number(s.total) === Number(oc.total_esperado)
    : false;

  const moneda_coincide = oc
    ? s.moneda === oc.moneda
    : false;

  return {
    json: {
      ...casos[i],
      documento: s,
      numero_oc: s.numero_oc ?? null,
      oc_valida: Boolean(oc),
      recepcion_confirmada: oc?.recepcion_confirmada ?? false,
      proveedor_coincide,
      total_coincide,
      moneda_coincide,
      campos_faltantes,
      error: item.json.error ?? ""
    }
  };
});
